def backfill_activity(apps, schema_editor):
    """Give every existing ticket an activity stamp.

    Without this, rows written before the column existed sort by the Coalesce
    fallback while new ones sort by a real stamp — correct, but it means the
    first page after deploy reshuffles for no visible reason. Newest public
    message if there is one, else the creation time.
    """
    CompanyRequest = apps.get_model("api", "CompanyRequest")
    TicketMessage = apps.get_model("api", "TicketMessage")
    newest = {}
    for m in (TicketMessage.objects.filter(internal=False)
              .order_by("request_id", "-created_at", "-id")
              .values("request_id", "created_at")):
        newest.setdefault(m["request_id"], m["created_at"])
    for r in CompanyRequest.objects.all().only("id", "created_at"):
        CompanyRequest.objects.filter(pk=r.pk).update(
            last_activity_at=newest.get(r.pk, r.created_at))


def unbackfill(apps, schema_editor):
    """Nothing to undo: the column goes with the rollback."""


